import { useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import { useNavigate } from "react-router-dom";
import "../styles/auth.css";

function Login() {
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const [role, setRole] = useState(null);
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");

  // ROLE SELECT
  if (!role) {
    return (
      <div className="split">
        <div className="left" onClick={() => setRole("citizen")}>
          <h1>Citizen</h1>
        </div>

        <div className="right" onClick={() => setRole("admin")}>
          <h1>Authority</h1>
        </div>
      </div>
    );
  }

  // LOGIN FUNCTION
  const handleLogin = () => {
    setError("");

    // AUTHORITY LOGIN
    if (role === "admin") {
      if (
        pin === "1234" &&
        email === "1234@gmail.com" &&
        pass === "1234@1234"
      ) {
        login({ role: "authority", email });
        navigate("/admin");
      } else {
        setError("Invalid Authority Credentials");
      }
    }

    // CITIZEN LOGIN
    else {
      if (email && pass) {
        login({ role: "citizen", email });
        navigate("/dashboard");
      } else {
        setError("Enter Email & Password");
      }
    }
  };

  return (
    <div className="auth">
      <h2>{role === "admin" ? "Authority Login" : "Citizen Login"}</h2>

      {role === "admin" && (
        <input
          placeholder="PIN"
          value={pin}
          onChange={(e) => setPin(e.target.value)}
        />
      )}

      <input
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />

      <input
        type="password"
        placeholder="Password"
        value={pass}
        onChange={(e) => setPass(e.target.value)}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      <button onClick={handleLogin}>Login</button>

      <p onClick={() => setRole(null)}>← Change Role</p>
    </div>
  );
}

export default Login;
